      "content": ""use client";

import { useCallback, useEffect, useMemo, useState } from "react";

export interface UseCounterResult {
  value: number | undefined;
  isLoading: boolean;
  error: string | null;
  increment: () => void;
  decrement: () => void;
  reset: () => void;
}

const DEFAULT_KEY = "counter-app-value";

function getStorageKey(): string {
  const envKey = process.env.NEXT_PUBLIC_COUNTER_STORAGE_KEY;
  return envKey && envKey.trim().length > 0 ? envKey : DEFAULT_KEY;
}

export function useCounter(): UseCounterResult {
  const [value, setValue] = useState<number | undefined>(undefined);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const storageKey = useMemo(() => getStorageKey(), []);

  useEffect(() => {
    try {
      const raw = window.localStorage.getItem(storageKey);
      if (raw === null) {
        setValue(0);
      } else {
        const parsed = Number(raw);
        setValue(Number.isFinite(parsed) ? parsed : 0);
      }
    } catch {
      setError("Unable to access local storage.");
      setValue(undefined);
    } finally {
      setIsLoading(false);
    }
  }, [storageKey]);

  const persist = useCallback(
    (next: number) => {
      try {
        window.localStorage.setItem(storageKey, String(next));
        setValue(next);
        setError(null);
      } catch {
        setError("Unable to persist counter value.");
      }
    },
    [storageKey]
  );

  const increment = useCallback(() => {
    persist((value ?? 0) + 1);
  }, [persist, value]);

  const decrement = useCallback(() => {
    persist((value ?? 0) - 1);
  }, [persist, value]);

  const reset = useCallback(() => {
    persist(0);
  }, [persist]);

  return { value, isLoading, error, increment, decrement, reset };
}
